input.old_string:
.dd { position: relative; font-size: 14px }
.dd-toggle { display: flex; align-items: center; gap: 8px; padding: 9px 14px; background: #fff; border: 1px solid #c9ced6; border-radius: 7px; cursor: pointer; user-select: none }
.dd-toggle .caret { font-size: 10px; color: #6a7280 }
.dd-list { position: absolute; right: 0; top: calc(100% + 6px); width: 200px; background: #fff; border: 1px solid #c9ced6; border-radius: 8px; box-shadow: 0 8px 20px rgba(24, 30, 40, 0.12); display: none; z-index: 5 }
.dd-list.open { display: block }
.dd-option { padding: 10px 14px; cursor: pointer }
.dd-option:hover { background: #eef1f5 }
.result { background: #fff; border: 1px solid #e4e6ea; border-radius: 8px; padding: 18px 20px; margin-bottom: 12px }
.result h2 { font-size: 16px; margin: 0 0 6px }
.result h2 a { color: #2456c4; text-decoration: none }
.result p { margin: 0; font-size: 14px; color: #4d5663; line-height: 1.55 }

